 mapping={'metadata':(root/fi['products']['peer_metadata']['path'],736,120),'tensor_ids':(fixture/'tensor_ids.hex',32,120),'checkpoint_gold':(fixture/'checkpoints.hex',1024,131072),'tail_gold':(fixture/'tail544.hex',1024,544),'catalog_mem':(data/'catalog.hex',512,128),'bias_mem':(data/'bias.words.hex',32,18432),'gamma_mem':(data/'gamma.words.hex',32,1024),'type_mem':(data/'type.words.hex',32,3072)};rows=[];calls=re.findall(r'\$readmemh\((.*?)\);',text,re.S);assert len(calls)==15
